// @FIGURE_CODE_BEGIN
(function () {
  var C = { teal: '#1a7f9c', barrier: '#d6a15c', screen: '#a6a6a6', dash: '#222', ink: '#111' };
  var W = 900, H = 600;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);
  var gA = draw.group(), gB = draw.group();

  var state = { y: 8, d: 25, view: 'Both side by side' };
  var phys = {};
  var Dphys = 1.0, LAM = 550e-9;

  /* ---------- helpers ---------- */
  function label(g, txt, x, y, o) {
    o = o || {};
    var t = g.text(txt).font({
      family: 'Georgia, "Times New Roman", serif',
      size: o.size || 20,
      style: (o.italic === false) ? 'normal' : 'italic',
      weight: (o.bold === false) ? 'normal' : 'bold'
    }).fill(o.fill || C.ink);
    t.attr({
      'paint-order': 'stroke', stroke: '#fff',
      'stroke-width': (o.halo === false ? 0 : 4.5), 'stroke-linejoin': 'round'
    });
    t.center(x, y);
    return t;
  }
  function head(g, x, y, ang, size, color) {
    var a = ang * Math.PI / 180, ux = Math.cos(a), uy = -Math.sin(a), px = -uy, py = ux;
    var p = [[x, y],
    [x - ux * size + px * size * 0.42, y - uy * size + py * size * 0.42],
    [x - ux * size - px * size * 0.42, y - uy * size - py * size * 0.42]];
    return g.polygon(p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' ')).fill(color).stroke('none');
  }
  function dblArrow(g, x1, y1, x2, y2, color, size, wdt) {
    var ang = Math.atan2(-(y2 - y1), (x2 - x1)) * 180 / Math.PI;
    g.line(x1, y1, x2, y2).stroke({ color: color, width: wdt || 1.4 });
    head(g, x2, y2, ang, size, color);
    head(g, x1, y1, ang + 180, size, color);
  }
  function dashLine(g, x1, y1, x2, y2, w) {
    return g.line(x1, y1, x2, y2).stroke({ color: C.dash, width: w || 1.1, dasharray: '6,4' });
  }
  function arcPath(g, cx, cy, r, a0, a1, color) {
    if (Math.abs(a1 - a0) < 0.4) return null;
    var r0 = a0 * Math.PI / 180, r1 = a1 * Math.PI / 180;
    var p0 = [cx + r * Math.cos(r0), cy - r * Math.sin(r0)];
    var p1 = [cx + r * Math.cos(r1), cy - r * Math.sin(r1)];
    var large = Math.abs(a1 - a0) > 180 ? 1 : 0;
    var sweep = (a1 > a0) ? 0 : 1;
    return g.path('M' + p0[0].toFixed(2) + ',' + p0[1].toFixed(2) + ' A' + r + ',' + r + ' 0 ' +
      large + ' ' + sweep + ' ' + p1[0].toFixed(2) + ',' + p1[1].toFixed(2))
      .fill('none').stroke({ color: color || C.dash, width: 1.1 });
  }
  function waveOnRay(g, x0, y0, ang, t0, t1, amp, wl) {
    var a = ang * Math.PI / 180, ux = Math.cos(a), uy = -Math.sin(a), px = -uy, py = ux;
    var pts = [];
    for (var t = t0; t <= t1; t += 1.5) {
      var s = amp * Math.sin(2 * Math.PI * (t - t0) / wl);
      pts.push((x0 + ux * t + px * s).toFixed(2) + ',' + (y0 + uy * t + py * s).toFixed(2));
    }
    g.polyline(pts.join(' ')).fill('none').stroke({ color: C.teal, width: 1.9, linecap: 'round' });
  }
  function tip(el, txt, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(txt, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }
  function hit(g, x1, y1, x2, y2, txt, title, body) {
    var l = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 16, opacity: 0 });
    return tip(l, txt, title, body);
  }
  function hitDot(g, x, y, r, txt, title, body) {
    var c = g.circle(r * 2).center(x, y).fill('#000').opacity(0);
    return tip(c, txt, title, body);
  }

  /* ---------- physics ---------- */
  function computePhys() {
    var ym = state.y / 1000;
    var sinT = ym / Math.sqrt(ym * ym + Dphys * Dphys);
    phys.sinT = sinT;
    phys.thetaDeg = Math.atan2(ym, Dphys) * 180 / Math.PI;
    phys.dl = state.d * 1e-6 * Math.abs(sinT);
    phys.m = phys.dl / LAM;
  }

  /* ---------- panel (a) ---------- */
  function drawPanelA() {
    var g = gA;
    var bx = 90, sx = 392, cy = 340, barTop = 118, barBot = 502, scrTop = 106, scrBot = 516;
    var sep = 42 + (state.d - 5) / 55 * 54;
    var s1 = cy - sep / 2, s2 = cy + sep / 2;
    var yv = (state.y / 20) * 152, py = cy - yv;

    var bar = g.rect(7, barBot - barTop).move(bx - 3.5, barTop).fill(C.barrier);
    tip(bar, 'Opaque barrier with two slits', 'Double-slit barrier',
      'Light of a single wavelength illuminates the barrier; only the two narrow slits let it through, so each slit acts as a coherent source.');
    g.rect(7, 7).move(bx - 3.5, s1 - 3.5).fill('#fff');
    g.rect(7, 7).move(bx - 3.5, s2 - 3.5).fill('#fff');

    var scr = g.rect(9, scrBot - scrTop).move(sx - 4.5, scrTop).fill(C.screen);
    tip(scr, 'Viewing screen', 'Screen', 'The fringe pattern is observed here, a distance D = 1.00 m from the slits.');
    label(g, 'Screen', sx + 42, scrTop - 6, { size: 17, italic: false, bold: false });

    /* slit labels */
    g.line(bx - 16, s1, bx - 5, s1).stroke({ color: '#000', width: 1.1 });
    g.line(bx - 16, s2, bx - 5, s2).stroke({ color: '#000', width: 1.1 });
    label(g, 'S₁', bx - 34, s1, { size: 17, bold: false });
    label(g, 'S₂', bx - 34, s2, { size: 17, bold: false });

    /* rays */
    var a1 = Math.atan2(-(py - s1), sx - bx) * 180 / Math.PI;
    var a2 = Math.atan2(-(py - s2), sx - bx) * 180 / Math.PI;
    var L1 = Math.hypot(sx - bx, py - s1), L2 = Math.hypot(sx - bx, py - s2);
    g.line(bx, s1, sx, py).stroke({ color: C.teal, width: 2.1 });
    g.line(bx, s2, sx, py).stroke({ color: C.teal, width: 2.1 });
    head(g, bx + Math.cos(a1 * Math.PI / 180) * L1 * 0.60, s1 - Math.sin(a1 * Math.PI / 180) * L1 * 0.60, a1, 11, C.teal);
    head(g, bx + Math.cos(a2 * Math.PI / 180) * L2 * 0.60, s2 - Math.sin(a2 * Math.PI / 180) * L2 * 0.60, a2, 11, C.teal);
    waveOnRay(g, bx, s1, a1, 36, 108, 7, 22);
    waveOnRay(g, bx, s2, a2, 36, 108, 7, 22);

    function offPt(x0, y0, ang, t, side, dist) {
      var a = ang * Math.PI / 180, ux = Math.cos(a), uy = -Math.sin(a);
      return [x0 + ux * t + side * uy * dist, y0 + uy * t - side * ux * dist];
    }
    var p1 = offPt(bx, s1, a1, L1 * 0.44, 1, 20);
    label(g, 'r₁', p1[0], p1[1], { size: 20 });
    var p2 = offPt(bx, s2, a2, L2 * 0.44, -1, 21);
    label(g, 'r₂', p2[0], p2[1], { size: 20 });

    /* dashed construction */
    dashLine(g, bx, cy, sx, cy);
    dashLine(g, bx, cy, sx, py);
    var angP = Math.atan2(yv, sx - bx) * 180 / Math.PI;
    arcPath(g, bx, cy, 48, 0, angP);
    var la = (angP >= 0 ? 1 : -1) * Math.max(Math.abs(angP) / 2, 3.2);
    var thx = bx + 68 * Math.cos(la * Math.PI / 180), thy = cy - 68 * Math.sin(la * Math.PI / 180);
    label(g, 'θ', thx, thy, { size: 20 });

    /* P and C */
    g.circle(10).center(sx, py).fill('#000');
    label(g, 'P', sx + 18, py - 15, { size: 17, bold: false });
    label(g, 'C', sx - 19, cy + 16, { size: 17, bold: false });

    /* y bracket */
    g.line(sx + 6, py, 448, py).stroke({ color: '#000', width: 0.9 });
    g.line(sx + 6, cy, 448, cy).stroke({ color: '#000', width: 0.9 });
    dblArrow(g, 439, py, 439, cy, '#000', 7.5);
    label(g, 'y', 421, (py + cy) / 2, { size: 20 });

    /* D bracket */
    var yD = 546;
    g.line(bx, barBot + 4, bx, yD + 11).stroke({ color: '#000', width: 0.9 });
    g.line(sx, scrBot + 4, sx, yD + 11).stroke({ color: '#000', width: 0.9 });
    dblArrow(g, bx, yD, sx, yD, '#000', 7.5);
    label(g, 'D', (bx + sx) / 2, yD - 15, { size: 20 });

    /* d bracket */
    g.line(22, s1, 46, s1).stroke({ color: '#000', width: 0.9 });
    g.line(22, s2, 46, s2).stroke({ color: '#000', width: 0.9 });
    dblArrow(g, 32, s1, 32, s2, '#000', 7.5);
    label(g, 'd', 15, cy, { size: 20 });

    label(g, '(a)', (bx + sx) / 2, 578, { size: 17, italic: false, bold: false });

    /* hover targets */
    hit(g, bx, s1, sx, py, 'r₁ — full path from S₁ to P (about 1 m)',
      'Path length r₁', 'r₁ is the whole journey of the wave from the upper slit to P — about a metre long. Its absolute value is irrelevant to the fringe pattern; only its difference from r₂ matters.');
    hit(g, bx, s2, sx, py, 'r₂ — full path from S₂ to P, longer than r₁ by Δl = ' + (phys.dl * 1e9).toFixed(0) + ' nm',
      'Path length r₂', 'r₂ exceeds r₁ by only Δl = d·sinθ, a fraction of a micron. That microscopic difference is what sets the relative phase of the two waves at P.');
    hit(g, 32, s1, 32, s2, 'd — slit separation (' + state.d + ' µm)',
      'Slit separation d', 'd is the distance between the two slits. Widening d increases Δl for the same viewing angle, packing more fringes into the same span of screen.');
    hit(g, bx, yD, sx, yD, 'D — slits-to-screen distance (1.00 m)',
      'Distance D', 'D is enormous compared with d (metres versus microns). That is exactly why the two rays to P can be treated as parallel in panel (b).');
    hit(g, 439, py, 439, cy, 'y — height of P above the centre point C (' + state.y.toFixed(1) + ' mm)',
      'Height y', 'y locates the observation point on the screen. Since tanθ = y/D, sliding P up the screen is the same as increasing θ — and hence Δl.');
    hitDot(g, thx, thy, 18, 'θ = ' + phys.thetaDeg.toFixed(3) + '° — angle of P seen from the slits',
      'Angle θ', 'θ is measured from the central axis to the line joining the slit midpoint to P. It is drawn hugely exaggerated here: the true value is well under one degree.');
  }

  /* ---------- panel (b) ---------- */
  function drawPanelB() {
    var g = gB;
    var bx = 540, barTop = 96, barBot = 508, cy = 300;
    var db = 118 + (state.d - 5) / 55 * 80;
    var s1y = cy - db / 2, s2y = cy + db / 2;
    var tv = Math.max(-1, Math.min(1, phys.sinT / 0.018));
    var thv = tv * 42;
    var a = thv * Math.PI / 180;
    var u = { x: Math.cos(a), y: -Math.sin(a) };

    var bar = g.rect(7, barBot - barTop).move(bx - 3.5, barTop).fill(C.barrier);
    tip(bar, 'Barrier, magnified near the slits', 'Near-slit magnification',
      'This is the same barrier as in (a), seen from extremely close up. Over this tiny region the two rays heading to the distant point P are effectively parallel.');
    g.rect(7, 7).move(bx - 3.5, s1y - 3.5).fill('#fff');
    g.rect(7, 7).move(bx - 3.5, s2y - 3.5).fill('#fff');

    /* reference horizontals + angle arcs at each slit */
    dashLine(g, bx, s1y, bx + 182, s1y);
    dashLine(g, bx, s2y, bx + 208, s2y);
    arcPath(g, bx, s1y, 74, 0, thv);
    arcPath(g, bx, s2y, 74, 0, thv);
    var half = (thv >= 0 ? 1 : -1) * Math.max(Math.abs(thv) / 2, 4);
    label(g, 'θ', bx + 95 * Math.cos(half * Math.PI / 180), s1y - 95 * Math.sin(half * Math.PI / 180), { size: 20 });
    label(g, 'θ', bx + 95 * Math.cos(half * Math.PI / 180), s2y - 95 * Math.sin(half * Math.PI / 180), { size: 20 });

    /* parallel rays */
    var L1 = 252, L2 = 288;
    var e1 = { x: bx + u.x * L1, y: s1y + u.y * L1 };
    var e2 = { x: bx + u.x * L2, y: s2y + u.y * L2 };
    g.line(bx, s1y, e1.x, e1.y).stroke({ color: C.teal, width: 2.1 });
    g.line(bx, s2y, e2.x, e2.y).stroke({ color: C.teal, width: 2.1 });
    head(g, e1.x, e1.y, thv, 12, C.teal);
    head(g, e2.x, e2.y, thv, 12, C.teal);
    label(g, 'to P', e1.x + 32, e1.y - 13, { size: 17, italic: false, bold: false });
    label(g, 'to P', e2.x + 32, e2.y - 13, { size: 17, italic: false, bold: false });

    /* right triangle: perpendicular from the leading slit onto the trailing ray */
    var A, B;
    if (thv >= 0) { A = { x: bx, y: s1y }; B = { x: bx, y: s2y }; }
    else { A = { x: bx, y: s2y }; B = { x: bx, y: s1y }; }
    var proj = db * Math.abs(Math.sin(a));
    var F = { x: B.x + u.x * proj, y: B.y + u.y * proj };
    var abx = B.x - A.x, aby = B.y - A.y;
    var dot = abx * u.x + aby * u.y;
    var nx = abx - dot * u.x, ny = aby - dot * u.y;
    var nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;

    dashLine(g, A.x, A.y, F.x, F.y, 1.2);
    if (proj > 10) {
      var s = 11;
      g.polyline([
        (F.x - u.x * s) + ',' + (F.y - u.y * s),
        (F.x - u.x * s - nx * s) + ',' + (F.y - u.y * s - ny * s),
        (F.x - nx * s) + ',' + (F.y - ny * s)
      ].join(' ')).fill('none').stroke({ color: '#000', width: 1.2 });
    }

    /* angle θ inside the small triangle, at the leading slit */
    var angAB = Math.atan2(-(B.y - A.y), B.x - A.x) * 180 / Math.PI;
    var angAF = Math.atan2(-(F.y - A.y), F.x - A.x) * 180 / Math.PI;
    arcPath(g, A.x, A.y, 46, angAB, angAF);
    var mid = (angAB + angAF) / 2;
    var tax = A.x + 64 * Math.cos(mid * Math.PI / 180) + 8;
    var tay = A.y - 64 * Math.sin(mid * Math.PI / 180);
    label(g, 'θ', tax, tay, { size: 20 });

    /* Δl bracket, pushed well off the ray */
    var off = 62;
    dashLine(g, B.x, B.y, B.x + nx * (off + 18), B.y + ny * (off + 18));
    dashLine(g, F.x, F.y, F.x + nx * (off + 18), F.y + ny * (off + 18));
    var q1 = { x: B.x + nx * off, y: B.y + ny * off }, q2 = { x: F.x + nx * off, y: F.y + ny * off };
    dblArrow(g, q1.x, q1.y, q2.x, q2.y, '#000', 8, 1.6);
    var mx = (q1.x + q2.x) / 2 + nx * 20, my = (q1.y + q2.y) / 2 + ny * 20;
    label(g, 'Δl', mx, my, { size: 20 });

    /* d bracket */
    g.line(492, s1y, bx - 14, s1y).stroke({ color: '#000', width: 0.9 });
    g.line(492, s2y, bx - 14, s2y).stroke({ color: '#000', width: 0.9 });
    dblArrow(g, 500, s1y, 500, s2y, '#000', 7.5);
    label(g, 'd', 482, cy, { size: 20 });

    label(g, '(b)', (bx + e2.x) / 2, 578, { size: 17, italic: false, bold: false });

    /* hover targets */
    hit(g, q1.x, q1.y, q2.x, q2.y,
      'Δl = d·sinθ = ' + (phys.dl * 1e9).toFixed(0) + ' nm = ' + phys.m.toFixed(2) + ' λ',
      'The extra path Δl', 'Δl is the whole difference between r₁ and r₂, isolated by dropping a perpendicular from one slit onto the other ray. It is the hypotenuse d times sinθ — and it alone decides the phase difference at P.');
    hit(g, A.x, A.y, F.x, F.y, 'Perpendicular from the leading slit — its foot cuts off Δl',
      'The perpendicular', 'Because the rays are parallel, the wavefront through the leading slit is perpendicular to them. Everything beyond that line is common to both paths, so the leftover segment Δl is the entire difference.');
    hit(g, bx, s1y, e1.x, e1.y, 'Ray from the upper slit toward P', 'Parallel rays',
      'At a screen one metre away, two rays that leave slits tens of microns apart differ in direction by a negligible amount, so we may treat them as exactly parallel here.');
    hit(g, bx, s2y, e2.x, e2.y, 'Ray from the lower slit toward P', 'Parallel rays',
      'At a screen one metre away, two rays that leave slits tens of microns apart differ in direction by a negligible amount, so we may treat them as exactly parallel here.');
    hit(g, 500, s1y, 500, s2y, 'd — slit separation (' + state.d + ' µm): the hypotenuse of the small triangle',
      'Slit separation d', 'In the small right triangle, d is the hypotenuse and Δl is the leg opposite θ, giving Δl = d·sinθ directly.');
  }

  /* ---------- readout (in the side panel, not on the drawing) ---------- */
  function drawReadout() {
    var el = document.getElementById('roLines');
    if (el) {
      el.innerHTML =
        'y = ' + state.y.toFixed(1) + ' mm &nbsp; D = 1.00 m<br>' +
        'θ = ' + phys.thetaDeg.toFixed(3) + '°<br>' +
        'd = ' + state.d + ' µm &nbsp; λ = 550 nm<br>' +
        'Δl = d·sinθ = ' + (phys.dl * 1e9).toFixed(0) + ' nm<br>' +
        'Δl / λ = ' + phys.m.toFixed(2);
    }
    var st = document.getElementById('roStatus');
    if (st) {
      var di = Math.abs(phys.m - Math.round(phys.m));
      if (di < 0.12) { st.textContent = '● constructive — P is BRIGHT (m = ' + Math.round(phys.m) + ')'; st.style.color = '#1a7f37'; }
      else if (di > 0.38) { st.textContent = '● destructive — P is DARK'; st.style.color = '#c02020'; }
      else { st.textContent = '● partial — between bright and dark'; st.style.color = '#7a6a20'; }
    }
  }

  /* ---------- view switching ---------- */
  function applyView() {
    var v = state.view;
    if (v.indexOf('(a)') >= 0) {
      draw.viewbox(0, 0, 458, 600);
      gA.attr('display', null); gB.attr('display', 'none');
    } else if (v.indexOf('(b)') >= 0) {
      draw.viewbox(462, 0, 438, 600);
      gA.attr('display', 'none'); gB.attr('display', null);
    } else {
      draw.viewbox(0, 0, 900, 600);
      gA.attr('display', null); gB.attr('display', null);
    }
  }

  function render() {
    computePhys();
    gA.clear(); gB.clear();
    drawPanelA();
    drawPanelB();
    drawReadout();
    applyView();
  }

  /* ---------- controls ---------- */
  window.update_pointHeight = function (v) { state.y = +v; render(); };
  window.update_slitSeparation = function (v) { state.d = +v; render(); };
  window.toggle_viewMode = function (v) { state.view = v; render(); };

  /* ---------- demo steps ---------- */
  var steps = [
    {
      title: 'The apparatus',
      narration: 'Both constructions are shown. In (a), light leaves two slits separated by d and travels a distance D to the screen. Point P sits a height y above the centre point C; rays r₁ and r₂ reach it along slightly different paths.',
      state: { viewMode: 'Both side by side', pointHeight: 8, slitSeparation: 25 }
    },
    {
      title: 'Slide P up the screen',
      narration: 'Now only the full apparatus. Move P upward: the angle θ between the centre line and the line to P grows, and r₁ becomes shorter than r₂ — but the difference is far too small to see at this scale.',
      state: { viewMode: 'Full apparatus (a)', pointHeight: 18, slitSeparation: 25 }
    },
    {
      title: 'Zoom in on the slits',
      narration: 'Because D is enormous compared with d, the two rays to P are essentially parallel. Dropping a perpendicular from the leading slit onto the other ray isolates the whole difference in one short segment, Δl.',
      state: { viewMode: 'Near-slit zoom (b)', pointHeight: 18, slitSeparation: 25 }
    },
    {
      title: 'Read the right triangle',
      narration: 'The triangle has hypotenuse d and its angle at the slit equals θ, so the isolated leg is exactly Δl = d·sinθ. Watch it shrink as P moves back toward the centre.',
      state: { viewMode: 'Near-slit zoom (b)', pointHeight: 3, slitSeparation: 25 }
    },
    {
      title: 'Widen the slits',
      narration: 'Hold the angle and widen d: Δl grows in direct proportion, so more bright fringes are packed into the same span of screen.',
      state: { viewMode: 'Near-slit zoom (b)', pointHeight: 8, slitSeparation: 55 }
    },
    {
      title: 'Both views at once',
      narration: 'Side by side, a screen-scale change in y and a micron-scale change in Δl move together. Whenever Δl is a whole number of wavelengths the waves arrive in phase and P is bright; a half-integer gives darkness.',
      state: { viewMode: 'Both side by side', pointHeight: 12, slitSeparation: 25 }
    }
  ];
  var cur = 0;
  function showStepText() {
    var s = steps[cur];
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepTitle').textContent = (cur + 1) + '. ' + s.title;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
  }
  function setSlider(id, v) {
    var inp = document.getElementById(id + 'Input');
    if (inp) inp.value = v;
    var out = document.getElementById(id + 'Val');
    if (out) out.value = v;
    if (id === 'pointHeight') state.y = +v; else state.d = +v;
  }
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    setSlider('pointHeight', s.state.pointHeight);
    setSlider('slitSeparation', s.state.slitSeparation);
    var sel = document.getElementById('viewModeInput');
    if (sel) sel.value = s.state.viewMode;
    state.view = s.state.viewMode;
    showStepText();
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

