// @FIGURE_CODE_BEGIN
(function () {
  var C = { teal: '#1c7d9c', barrier: '#d6a55f', screen: '#a8a8a8', dash: '#1a1a1a', ink: '#111' };
  var W = 920, H = 600;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);
  var gA = draw.group(), gB = draw.group();

  var state = { y: 8, d: 25, view: 'Both side by side' };
  var phys = {};
  var Dphys = 1.0, LAM = 550e-9;
  var DPX = 286, YMAX = 208, KT = 2.25;

  /* ---------- helpers ---------- */
  function yToPix(y) { return YMAX * Math.tanh(KT * y / 20) / Math.tanh(KT); }

  function label(g, txt, x, y, o) {
    o = o || {};
    var t = g.text(txt).font({
      family: 'Georgia, "Times New Roman", serif',
      size: o.size || 19,
      style: (o.italic === false) ? 'normal' : 'italic',
      weight: (o.bold === false) ? 'normal' : 'bold'
    }).fill(o.fill || C.ink);
    t.attr({
      'paint-order': 'stroke', stroke: '#fff',
      'stroke-width': (o.halo === false ? 0 : 4.2), 'stroke-linejoin': 'round'
    });
    t.center(x, y);
    return t;
  }
  function head(g, x, y, ang, size, color) {
    var a = ang * Math.PI / 180, ux = Math.cos(a), uy = -Math.sin(a), px = -uy, py = ux;
    var p = [[x, y],
    [x - ux * size + px * size * 0.42, y - uy * size + py * size * 0.42],
    [x - ux * size - px * size * 0.42, y - uy * size - py * size * 0.42]];
    return g.polygon(p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' ')).fill(color).stroke('none');
  }
  function dblArrow(g, x1, y1, x2, y2, color, size, wdt) {
    var ang = Math.atan2(-(y2 - y1), (x2 - x1)) * 180 / Math.PI;
    var L = Math.hypot(x2 - x1, y2 - y1);
    g.line(x1, y1, x2, y2).stroke({ color: color, width: wdt || 1.3 });
    if (L > 9) { head(g, x2, y2, ang, size, color); head(g, x1, y1, ang + 180, size, color); }
  }
  function dashLine(g, x1, y1, x2, y2, w) {
    return g.line(x1, y1, x2, y2).stroke({ color: C.dash, width: w || 1.1, dasharray: '6,4' });
  }
  function thin(g, x1, y1, x2, y2) { return g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 0.9 }); }
  function arcPath(g, cx, cy, r, a0, a1, color) {
    if (Math.abs(a1 - a0) < 0.6) return null;
    var r0 = a0 * Math.PI / 180, r1 = a1 * Math.PI / 180;
    var p0 = [cx + r * Math.cos(r0), cy - r * Math.sin(r0)];
    var p1 = [cx + r * Math.cos(r1), cy - r * Math.sin(r1)];
    var large = Math.abs(a1 - a0) > 180 ? 1 : 0;
    var sweep = (a1 > a0) ? 0 : 1;
    return g.path('M' + p0[0].toFixed(2) + ',' + p0[1].toFixed(2) + ' A' + r + ',' + r + ' 0 ' +
      large + ' ' + sweep + ' ' + p1[0].toFixed(2) + ',' + p1[1].toFixed(2))
      .fill('none').stroke({ color: color || C.dash, width: 1.1 });
  }
  function waveOnRay(g, x0, y0, ang, t0, t1, amp, wl) {
    var a = ang * Math.PI / 180, ux = Math.cos(a), uy = -Math.sin(a), px = -uy, py = ux;
    var pts = [];
    for (var t = t0; t <= t1; t += 1.4) {
      var s = amp * Math.sin(2 * Math.PI * (t - t0) / wl);
      pts.push((x0 + ux * t + px * s).toFixed(2) + ',' + (y0 + uy * t + py * s).toFixed(2));
    }
    g.polyline(pts.join(' ')).fill('none').stroke({ color: C.teal, width: 1.9, linecap: 'round' });
  }
  function tip(el, txt, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(txt, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }
  function hit(g, x1, y1, x2, y2, txt, title, body) {
    return tip(g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 16, opacity: 0 }), txt, title, body);
  }
  function hitDot(g, x, y, r, txt, title, body) {
    return tip(g.circle(r * 2).center(x, y).fill('#000').opacity(0), txt, title, body);
  }

  /* ---------- physics ---------- */
  function computePhys() {
    var ym = state.y / 1000;
    var sinT = ym / Math.sqrt(ym * ym + Dphys * Dphys);
    phys.sinT = sinT;
    phys.thetaDeg = Math.atan2(ym, Dphys) * 180 / Math.PI;
    phys.dl = state.d * 1e-6 * Math.abs(sinT);
    phys.m = phys.dl / LAM;
    phys.drawDeg = Math.atan2(yToPix(state.y), DPX) * 180 / Math.PI;
  }

  /* ---------- panel (a) : full apparatus ---------- */
  function drawPanelA() {
    var g = gA;
    var bx = 74, barTop = 152, barBot = 518;
    var sx = bx + DPX, scrTop = 98, scrBot = 514, cy = 306;
    var sepHalf = (60 + (state.d - 5) / 55 * 90) / 2;
    var s1 = cy - sepHalf, s2 = cy + sepHalf;
    var yv = yToPix(state.y), py = cy - yv;

    /* barrier + slits */
    var bar = g.rect(7, barBot - barTop).move(bx - 3.5, barTop).fill(C.barrier);
    tip(bar, 'Opaque barrier with two slits', 'Double-slit barrier',
      'Light of a single wavelength illuminates the barrier; only the two narrow slits let it through, so each slit acts as a coherent source.');
    g.rect(7, 8).move(bx - 3.5, s1 - 4).fill('#fff');
    g.rect(7, 8).move(bx - 3.5, s2 - 4).fill('#fff');

    /* screen */
    var scr = g.rect(9, scrBot - scrTop).move(sx - 4.5, scrTop).fill(C.screen);
    tip(scr, 'Viewing screen, a distance D from the slits', 'Screen',
      'The fringe pattern is observed here, a distance D = 1.00 m from the slits.');

    /* dashed construction (drawn before rays) */
    dashLine(g, bx, cy, sx, cy);
    dashLine(g, bx, cy, sx, py);

    /* rays */
    var a1 = Math.atan2(-(py - s1), sx - bx) * 180 / Math.PI;
    var a2 = Math.atan2(-(py - s2), sx - bx) * 180 / Math.PI;
    var L1 = Math.hypot(sx - bx, py - s1), L2 = Math.hypot(sx - bx, py - s2);
    g.line(bx, s1, sx, py).stroke({ color: C.teal, width: 2.1 });
    g.line(bx, s2, sx, py).stroke({ color: C.teal, width: 2.1 });
    head(g, bx + Math.cos(a1 * Math.PI / 180) * L1 * 0.58, s1 - Math.sin(a1 * Math.PI / 180) * L1 * 0.58, a1, 11, C.teal);
    head(g, bx + Math.cos(a2 * Math.PI / 180) * L2 * 0.58, s2 - Math.sin(a2 * Math.PI / 180) * L2 * 0.58, a2, 11, C.teal);
    waveOnRay(g, bx, s1, a1, 24, 146, 8, 26);
    waveOnRay(g, bx, s2, a2, 24, 146, 8, 26);

    /* angle arc at slit midpoint */
    var angP = Math.atan2(yv, DPX) * 180 / Math.PI;
    arcPath(g, bx, cy, 42, 0, angP);

    /* P dot */
    g.circle(10).center(sx, py).fill('#000');

    /* brackets (geometry) */
    thin(g, sx + 5, py, 424, py);
    thin(g, sx + 5, cy, 424, cy);
    dblArrow(g, 412, py, 412, cy, '#000', 7.5);

    var yD = 552;
    thin(g, bx, barBot + 4, bx, yD + 10);
    thin(g, sx, scrBot + 4, sx, yD + 10);
    dblArrow(g, bx, yD, sx, yD, '#000', 7.5);

    thin(g, 14, s1, 44, s1);
    thin(g, 14, s2, 44, s2);
    dblArrow(g, 26, s1, 26, s2, '#000', 7.5);

    /* ---- labels last, on top ---- */
    label(g, 'Screen', sx + 44, scrTop - 4, { size: 17, italic: false, bold: false });
    label(g, 'S₁', bx - 22, s1, { size: 17, bold: false });
    label(g, 'S₂', bx - 22, s2, { size: 17, bold: false });
    label(g, 'd', 9, cy, { size: 19 });
    label(g, 'y', 392, (py + cy) / 2, { size: 19 });
    label(g, 'D', (bx + sx) / 2, yD - 17, { size: 19 });
    label(g, 'P', sx + 16, py - 15, { size: 17, bold: false });
    label(g, 'C', sx - 18, cy + 16, { size: 17, bold: false });

    /* r1 above upper ray, r2 below lower ray — no crowding between them */
    function offPt(x0, y0, ang, t, side, dist) {
      var a = ang * Math.PI / 180, ux = Math.cos(a), uy = -Math.sin(a);
      return [x0 + ux * t + side * uy * dist, y0 + uy * t - side * ux * dist];
    }
    var p1 = offPt(bx, s1, a1, L1 * 0.46, 1, 21);
    label(g, 'r₁', p1[0], p1[1], { size: 19 });
    var p2 = offPt(bx, s2, a2, L2 * 0.52, -1, 22);
    label(g, 'r₂', p2[0], p2[1], { size: 19 });

    /* theta label inside the wedge, kept off both dashed lines */
    var la = angP * 0.42;
    var thx = bx + 52 * Math.cos(la * Math.PI / 180), thy = cy - 52 * Math.sin(la * Math.PI / 180);
    label(g, 'θ', thx, thy, { size: 18 });
    label(g, '(a)', (bx + sx) / 2, 586, { size: 17, italic: false, bold: false });

    /* hover / click targets */
    hit(g, bx, s1, sx, py, 'r₁ — full path from S₁ to P (about 1 m)',
      'Path length r₁', 'r₁ is the whole journey of the wave from the upper slit to P — about a metre long. Its absolute value is irrelevant to the fringe pattern; only its difference from r₂ matters.');
    hit(g, bx, s2, sx, py, 'r₂ — full path from S₂ to P, longer than r₁ by Δl = ' + (phys.dl * 1e9).toFixed(0) + ' nm',
      'Path length r₂', 'r₂ exceeds r₁ by only Δl = d·sinθ, a fraction of a micron. That microscopic difference alone sets the relative phase of the two waves at P.');
    hit(g, 26, s1, 26, s2, 'd — slit separation (' + state.d + ' µm)',
      'Slit separation d', 'd is the distance between the two slits. Widening d increases Δl for the same viewing angle, packing more fringes into the same span of screen.');
    hit(g, bx, yD, sx, yD, 'D — slits-to-screen distance (1.00 m)',
      'Distance D', 'D is enormous compared with d (metres versus microns). That is exactly why the two rays to P can be treated as parallel in panel (b).');
    hit(g, 412, py, 412, cy, 'y — height of P above the centre point C (' + state.y.toFixed(1) + ' mm)',
      'Height y', 'y locates the observation point on the screen. Since tanθ = y/D, sliding P up the screen is the same as increasing θ — and hence Δl.');
    hitDot(g, thx, thy, 20, 'θ = ' + phys.thetaDeg.toFixed(3) + '° — direction of P seen from the slits (drawn exaggerated)',
      'Angle θ', 'θ is measured from the central axis to the line joining the slit midpoint to P. It is drawn hugely exaggerated here: the true value is well under one degree.');
    hitDot(g, sx, py, 14, 'P — the observation point on the screen', 'Point P',
      'Whether P is bright or dark depends only on how many wavelengths fit into Δl, not on how far the light has travelled to get there.');
  }

  /* ---------- panel (b) : near-slit magnification ---------- */
  function drawPanelB() {
    var g = gB;
    var bx = 560, barTop = 104, barBot = 520, cy = 300;
    var dbHalf = (130 + (state.d - 5) / 55 * 110) / 2;
    var s1y = cy - dbHalf, s2y = cy + dbHalf;
    var thv = phys.drawDeg;
    var a = thv * Math.PI / 180;
    var u = { x: Math.cos(a), y: -Math.sin(a) };
    var sA = Math.abs(Math.sin(a));

    var bar = g.rect(7, barBot - barTop).move(bx - 3.5, barTop).fill(C.barrier);
    tip(bar, 'The same barrier, magnified near the slits', 'Near-slit magnification',
      'This is the same barrier as in (a), seen from extremely close up. Over this tiny region the two rays heading to the distant point P are effectively parallel.');
    g.rect(7, 8).move(bx - 3.5, s1y - 4).fill('#fff');
    g.rect(7, 8).move(bx - 3.5, s2y - 4).fill('#fff');

    /* dashed horizontal references */
    dashLine(g, bx, s1y, bx + 288, s1y);
    dashLine(g, bx, s2y, bx + 296, s2y);

    /* parallel rays, clipped to the frame */
    function rayLen(y0) {
      var lim = 306;
      if (sA > 0.03) lim = Math.min(lim, (thv > 0 ? (y0 - 44) : (546 - y0)) / sA);
      lim = Math.min(lim, (846 - bx) / Math.cos(a));
      return Math.max(70, lim);
    }
    var L1 = rayLen(s1y), L2 = rayLen(s2y);
    var e1 = { x: bx + u.x * L1, y: s1y + u.y * L1 };
    var e2 = { x: bx + u.x * L2, y: s2y + u.y * L2 };
    g.line(bx, s1y, e1.x, e1.y).stroke({ color: C.teal, width: 2.1 });
    g.line(bx, s2y, e2.x, e2.y).stroke({ color: C.teal, width: 2.1 });
    head(g, e1.x, e1.y, thv, 12, C.teal);
    head(g, e2.x, e2.y, thv, 12, C.teal);

    /* angle arcs at the slits */
    arcPath(g, bx, s1y, 70, 0, thv);
    arcPath(g, bx, s2y, 70, 0, thv);

    /* right triangle: perpendicular from the leading slit onto the other ray */
    var A, B;
    if (thv >= 0) { A = { x: bx, y: s1y }; B = { x: bx, y: s2y }; }
    else { A = { x: bx, y: s2y }; B = { x: bx, y: s1y }; }
    var proj = 2 * dbHalf * sA;
    var F = { x: B.x + u.x * proj, y: B.y + u.y * proj };
    var abx = B.x - A.x, aby = B.y - A.y;
    var dot = abx * u.x + aby * u.y;
    var nx = abx - dot * u.x, ny = aby - dot * u.y;
    var nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;

    dashLine(g, A.x, A.y, F.x, F.y, 1.2);
    if (proj > 12) {
      var s = 11;
      g.polyline([
        (F.x - u.x * s) + ',' + (F.y - u.y * s),
        (F.x - u.x * s - nx * s) + ',' + (F.y - u.y * s - ny * s),
        (F.x - nx * s) + ',' + (F.y - ny * s)
      ].join(' ')).fill('none').stroke({ color: '#000', width: 1.2 });
    }

    /* theta inside the small triangle */
    var angAB = Math.atan2(-(B.y - A.y), B.x - A.x) * 180 / Math.PI;
    var angAF = Math.atan2(-(F.y - A.y), F.x - A.x) * 180 / Math.PI;
    arcPath(g, A.x, A.y, 48, angAB, angAF);

    /* Δl bracket, pushed clear of the ray */
    var off = 70;
    dashLine(g, B.x, B.y, B.x + nx * (off + 22), B.y + ny * (off + 22));
    dashLine(g, F.x, F.y, F.x + nx * (off + 22), F.y + ny * (off + 22));
    var q1 = { x: B.x + nx * off, y: B.y + ny * off }, q2 = { x: F.x + nx * off, y: F.y + ny * off };
    dblArrow(g, q1.x, q1.y, q2.x, q2.y, '#000', 8, 1.5);

    /* d bracket */
    thin(g, 500, s1y, 551, s1y);
    thin(g, 500, s2y, 551, s2y);
    dblArrow(g, 512, s1y, 512, s2y, '#000', 7.5);

    /* ---- labels last ---- */
    var hAng = thv * 0.5, hr = 84;
    label(g, 'θ', bx + hr * Math.cos(hAng * Math.PI / 180), s1y - hr * Math.sin(hAng * Math.PI / 180), { size: 18 });
    label(g, 'θ', bx + hr * Math.cos(hAng * Math.PI / 180), s2y - hr * Math.sin(hAng * Math.PI / 180), { size: 18 });
    var mid = (angAB + angAF) / 2;
    var tax = A.x + 66 * Math.cos(mid * Math.PI / 180), tay = A.y - 66 * Math.sin(mid * Math.PI / 180);
    label(g, 'θ', tax, tay, { size: 18 });
    label(g, 'to P', e1.x + 30, e1.y - 14, { size: 17, italic: false, bold: false });
    label(g, 'to P', e2.x + 30, e2.y - 14, { size: 17, italic: false, bold: false });
    label(g, 'd', 490, cy, { size: 19 });
    var mx = (q1.x + q2.x) / 2 + nx * 22, my = (q1.y + q2.y) / 2 + ny * 22;
    label(g, 'Δl', mx, my, { size: 19 });
    label(g, '(b)', bx + 150, 586, { size: 17, italic: false, bold: false });

    /* hover / click targets */
    hit(g, q1.x, q1.y, q2.x, q2.y,
      'Δl = d·sinθ = ' + (phys.dl * 1e9).toFixed(0) + ' nm = ' + phys.m.toFixed(2) + ' λ',
      'The extra path Δl', 'Δl is the whole difference between r₁ and r₂, isolated by dropping a perpendicular from one slit onto the other ray. It is the hypotenuse d times sinθ — and it alone decides the phase difference at P.');
    hit(g, A.x, A.y, F.x, F.y, 'Perpendicular from the leading slit — its foot cuts off Δl',
      'The perpendicular', 'Because the rays are parallel, the wavefront through the leading slit is perpendicular to them. Everything beyond that line is common to both paths, so the leftover segment Δl is the entire difference.');
    hit(g, bx, s1y, e1.x, e1.y, 'Ray from the upper slit heading toward P', 'Parallel rays',
      'At a screen one metre away, two rays that leave slits tens of microns apart differ in direction by a negligible amount, so we may treat them as exactly parallel here.');
    hit(g, bx, s2y, e2.x, e2.y, 'Ray from the lower slit heading toward P', 'Parallel rays',
      'At a screen one metre away, two rays that leave slits tens of microns apart differ in direction by a negligible amount, so we may treat them as exactly parallel here.');
    hit(g, 512, s1y, 512, s2y, 'd — slit separation (' + state.d + ' µm): the hypotenuse of the small triangle',
      'Slit separation d', 'In the small right triangle, d is the hypotenuse and Δl is the leg opposite θ, giving Δl = d·sinθ directly.');
    hitDot(g, tax, tay, 18, 'Same angle θ appears inside the little triangle', 'Why the angle repeats',
      'The rays make angle θ with the horizontal, and the perpendicular makes angle θ with the barrier: the triangle’s angle at the slit is the very same θ that locates P on the screen.');
  }

  /* ---------- side-panel readout ---------- */
  function drawReadout() {
    var el = document.getElementById('roLines');
    if (el) {
      el.innerHTML =
        'y = ' + state.y.toFixed(1) + ' mm &nbsp; D = 1.00 m<br>' +
        'θ = ' + phys.thetaDeg.toFixed(3) + '°<br>' +
        'd = ' + state.d + ' µm &nbsp; λ = 550 nm<br>' +
        'Δl = d·sinθ = ' + (phys.dl * 1e9).toFixed(0) + ' nm<br>' +
        'Δl / λ = ' + phys.m.toFixed(2);
    }
    var st = document.getElementById('roStatus');
    if (st) {
      var di = Math.abs(phys.m - Math.round(phys.m));
      if (di < 0.12) { st.textContent = '● constructive — P is BRIGHT (m = ' + Math.round(phys.m) + ')'; st.style.color = '#1a7f37'; }
      else if (di > 0.38) { st.textContent = '● destructive — P is DARK'; st.style.color = '#c02020'; }
      else { st.textContent = '● partial — between bright and dark'; st.style.color = '#7a6a20'; }
    }
  }

  /* ---------- view switching ---------- */
  function applyView() {
    var v = state.view;
    if (v.indexOf('(a)') >= 0) {
      draw.viewbox(0, 0, 452, 600);
      gA.attr('display', null); gB.attr('display', 'none');
